#[cfg(test)]
mod tests {
    use super::*;
    use crate::acp::schema::FileSystemCapabilities;

    #[test]
    fn a_session_belongs_to_the_connection_that_made_it() {
        // The check that keeps two editors apart: a session id means nothing outside
        // the connection that created it.
        let mut conn = Connection::new("c1", 1, ClientCapabilities::default(), None, 0);
        assert!(!conn.has_session("s1"));
        conn.sessions.push(Session {
            id: "s1".into(),
            cwd: "/w".into(),
            additional_directories: vec![],
            created_ms: 0,
        });
        assert!(conn.has_session("s1"));
        assert_eq!(conn.session("s1").expect("present").cwd, "/w");
        assert!(conn.session("s2").is_none());
    }

    #[test]
    fn capabilities_are_read_from_what_the_client_granted() {
        // The ACP inversion: these are the AGENT's permissions, declared by the side
        // that will service them.
        let conn = Connection::new(
            "c1",
            1,
            ClientCapabilities {
                fs: FileSystemCapabilities {
                    read_text_file: true,
                    write_text_file: false,
                },
                terminal: false,
                ..ClientCapabilities::default()
            },
            None,
            0,
        );
        assert!(conn.can_read_files());
        assert!(!conn.can_write_files());
        assert!(!conn.can_run_terminals());
    }
}
